def two_sum(nums, target):
    # Indices ordered by value, so we can still report original positions.
    order = sorted(range(len(nums)), key=lambda i: nums[i])
    left, right = 0, len(nums) - 1
    while left < right:
        total = nums[order[left]] + nums[order[right]]
        if total == target:
            return sorted([order[left], order[right]])
        if total < target:
            left += 1
        else:
            right -= 1
    return []

class Solution {
    public int[] twoSum(int[] nums, int target) {
        // Indices ordered by value, so we can still report original positions.
        Integer[] order = new Integer[nums.length];
        for (int i = 0; i < nums.length; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(nums[a], nums[b]));
        int left = 0, right = nums.length - 1;
        while (left < right) {
            int sum = nums[order[left]] + nums[order[right]];
            if (sum == target) {
                int a = order[left], b = order[right];
                return new int[]{Math.min(a, b), Math.max(a, b)};
            }
            if (sum < target) left++;
            else right--;
        }
        return new int[0];
    }
}

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        // Indices ordered by value, so we can still report original positions.
        vector<int> order(nums.size());
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return nums[a] < nums[b]; });
        int left = 0, right = nums.size() - 1;
        while (left < right) {
            int sum = nums[order[left]] + nums[order[right]];
            if (sum == target) {
                return {min(order[left], order[right]), max(order[left], order[right])};
            }
            if (sum < target) left++;
            else right--;
        }
        return {};
    }
};

